from calculator_class import Calculatorcalculator = Calculator()class CalculatorApp:    def __init__(self):        self.calculator = calculator        self.calculator_menu = {            "1.":("ADDITION",self.calculator.Addition),            "2.":("SUBTRACTION",self.calculator.Subtraction),            "3.":("MULTIPLICATION",self.calculator.Multiplication),            "4.":("DIVISION",self.calculator.Division)}        for key, value in self.calculator_menu.items():            print(f"{key}: {value[0]}")    def main(self):        while True:            choice = float(input("Enter your choice 1 TO 4: "))            if choice not in self.calculator_menu.keys():                print("Invalid choice")                continue            number_1 = float(int("Enter first number"))            number_2 = float(int("Enter second number"))